import re
import sys

def eval_expression(expr):
    """
    Evaluates a mathematical expression string with correct order of operations.
    Supports parentheses, unary minus, integer/float division,
    and raises ZeroDivisionError if dividing by zero.

    Args:
        expr (str): A string representing a valid mathematical expression.

    Returns:
        float or int: The evaluated result of the expression.

    Raises:
        ZeroDivisionError: If a division by zero is detected.
        ValueError: If the expression contains invalid syntax.
    """
    def tokenize(expression):
        token_regex = r'\d+\.?\d*|[-+*/()]|\s+'
        tokens = []
        for match in re.finditer(token_regex, expression):
            tokens.append(match.group())
        tokens = [t for t in tokens if t]  # Remove empty strings
        return tokens

    def parse_and_evaluate(tokens):
        value_stack = []
        op_stack = []
        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if re.fullmatch(r'\d+(\.\d+)?', token):
                value_stack.append(float(token))
            elif token == '(':
                op_stack.append(token)
            elif token in precedence:
                while (op_stack and op_stack[-1] != '(' and 
                       precedence[op_stack[-1]] >= precedence[token]):
                    apply_operator(value_stack, op_stack)
                op_stack.append(token)
            elif token == ')':
                while op_stack and op_stack[-1] != '(':
                    apply_operator(value_stack, op_stack)
                if not op_stack:
                    raise ValueError("Mismatched parentheses")
                op_stack.pop()
            i += 1
        while op_stack:
            apply_operator(value_stack, op_stack)

        return value_stack[0] if value_stack else 0

    def apply_operator(value_stack, op_stack):
        operator = op_stack.pop()
        b = value_stack.pop()
        a = value_stack.pop()
        try:
            if operator == '+':
                res = a + b
            elif operator == '-':
                res = a - b
            elif operator == '*':
                res = a * b
            elif operator == '/':
                if b == 0:
                    raise ZeroDivisionError("division by zero")
                res = a / b
            else:
                raise ValueError(f"Unknown operator: {operator}")
            value_stack.append(res)
        except Exception as e:
            if isinstance(e, ZeroDivisionError):
                raise
            raise

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    return parse_and_evaluate(tokens)
